// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint128 amount1, uint128 amount2, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount1 > 0);
        uint256 a1 = uint256(amount1);
        uint256 a2 = uint256(amount2);

        vm.deal(actor, a1 + a2);

        vm.prank(actor);
        c.Put{value: a1}(0);
        vm.prank(actor);
        c.Put{value: a2}(0);

        (, uint256 bal) = c.Acc(actor);
        assertTrue(bal == a1 + a2);
    }
}
